import {verifyPinned} from './signature-pins.mjs';
import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {readFileSync,writeFileSync} from 'node:fs';import {createHash} from 'node:crypto';
const git=(...a)=>execFileSync('git',a,{encoding:'utf8',timeout:30000}).trim();const blob=(sha,p)=>execFileSync('git',['show',sha+':'+p],{timeout:30000});const hash=b=>createHash('sha256').update(b).digest('hex');
const root='sandbox-release/signature-ui/',open='.github/sandbox-approvals/signature-ui-open.json',close='.github/sandbox-approvals/signature-ui-close.json';
assert.equal(process.env.GITHUB_REPOSITORY,'rohimgavino/Wedding-Planner');assert.equal(process.env.GITHUB_REF,'refs/heads/sandbox/doku-checkout');assert.equal(process.env.GITHUB_EVENT_NAME,'push');
const e=JSON.parse(readFileSync(process.env.GITHUB_EVENT_PATH));for(const k of ['forced','created','deleted'])assert.equal(e[k],false);assert.equal(e.after,git('rev-parse','HEAD'));assert.equal(e.before,git('show','-s','--format=%P','HEAD'));assert.match(e.before,/^[0-9a-f]{40}$/);
git('merge-base','--is-ancestor','91c27e21a0fee49f0459da10a077612e29ddd223',e.before);
for(const rev of [e.before,e.after])assert.equal(git('rev-parse',rev+':sandbox-release/signature-closed/api'),'c497bde8436c7320cc115703036f4bf3a049dc07');
const diff=git('diff','--name-status',e.before,e.after);const match=/^[AM]\t(.+)$/.exec(diff);assert.ok(match);const path=match[1];assert.ok([open,close].includes(path));const markerBytes=blob(e.after,path);const m=JSON.parse(markerBytes);assert.equal(markerBytes.toString(),JSON.stringify(m)+'\n');assert.deepEqual(Object.keys(m).sort(),['authorization','from','parent','to']);assert.equal(m.parent,e.before);assert.equal(m.authorization,'APPROVE EXACT HARNESS UI BOOLEAN ONLY');assert.equal(typeof m.from,'boolean');assert.equal(typeof m.to,'boolean');assert.notEqual(m.from,m.to);assert.equal(m.to,path===open);
const last=git('log','-1','--format=%H',e.before,'--',open,close);const prev=last?JSON.parse(blob(last,git('diff-tree','--no-commit-id','--name-only','-r',last))):{to:false};assert.equal(m.from,prev.to);
const pins={"sandbox-release/signature-ui/baseline.json": "83e954baf7b0f11dcc9bb7f2b263284c3a75828872e995c9316e591592774656", "sandbox-release/signature-ui/config-closed.txt": "16282b83e90505eb27e79bc29760ca107b3361d014180c82840b637bf286ad7c", "sandbox-release/signature-ui/config-open.txt": "e9c4bf60b37250c4457d1a638ccef1ffcb00ac8a28a6e8e387a073471151224c", "sandbox-release/signature-ui/harness/app.mjs": "578cde381e4ad9c850b4c0a590c784df31b8a1240ad5b813deba9b3162b3c5e0", "sandbox-release/signature-ui/harness/catalog.json": "09d136045446ab4d51b5dd0749a3e421a888211ce9ce82f05c9298003913d25c", "sandbox-release/signature-ui/harness/checkout-client.mjs": "260e0f3ef68bfbb6fd9091ae769ea383ea48987493a6a78e1d621e582c257a90", "sandbox-release/signature-ui/harness/index.html": "dab8ff9f92a7ee5e8a10a9ed21a9d83981d907604f284927abf04e4ed5294e06", "sandbox-release/signature-ui/harness/public-config.offline.txt": "1cd2cdc8322214ba747fab9343054738645b7b70e345f85ccc71b40c4b7a9dc3", "sandbox-release/signature-ui/harness/public-config.txt": "16282b83e90505eb27e79bc29760ca107b3361d014180c82840b637bf286ad7c", "sandbox-release/signature-ui/harness/style.css": "56b18b61f26ffeb720432964b22b9985ee52d2e04be8b130781754f47c075a99", "sandbox-release/signature-ui/harness/timeout-probe.mjs": "16c64e643f902a4500a8106127c1da3fd0ec67147507f60fa3945d1eb5dcb6ef", "sandbox-release/signature-ui/harness/worker.mjs": "5c186d2cd0986b14b0a632679a9f52340902298e1f344605e68592b6bb331cdd", "sandbox-release/signature-ui/harness/workspace-intent-client.mjs": "ddf5cf3d57f1944eef52facecf94fe8afffff017850e19c04ce3e6bea93c0aed", "sandbox-release/signature-ui/harness/workspace-inventory.mjs": "92d83c125f0cec4096b4e29af10fc2aae80c2375e35bd849a6d51e326b2b7d5c", "sandbox-release/signature-ui/harness/wrangler.json": "5ce2c26cb2e6952a700d247492603e2c074db5745a073db106b27aa94b65e771"};
for(const [p,h] of Object.entries(pins)){assert.equal(hash(blob(e.before,p)),h,p);assert.equal(hash(blob(e.after,p)),h,p);const canonical=Buffer.from(readFileSync(p,'utf8').replace(/\r\n/g,'\n'));assert.equal(hash(canonical),h,p);writeFileSync(p,canonical);}
verifyPinned();
const baseline=JSON.parse(readFileSync(root+'baseline.json'));const closed=readFileSync(root+'config-closed.txt'),opened=readFileSync(root+'config-open.txt');assert.equal(hash(closed),baseline.closed);assert.equal(hash(opened),baseline.open);assert.deepEqual(JSON.parse(opened),{...JSON.parse(closed),checkoutEnabled:true});assert.equal(JSON.parse(closed).checkoutEnabled,false);
for(const [p,h] of Object.entries(baseline.files))assert.equal(hash(readFileSync(root+'harness/'+p)),h,p);
writeFileSync('sandbox-release/signature-closed/harness/public-config.txt',m.to?opened:closed);writeFileSync(root+'harness/public-config.txt',m.to?opened:closed);const expected={...JSON.parse(closed),checkoutEnabled:m.to};assert.deepEqual(JSON.parse(readFileSync(root+'harness/public-config.txt')),expected);
console.log(JSON.stringify({validated:true,onlyBooleanChanged:true,from:m.from,to:m.to,worker:'pp-doku-sbx-harness-20261102',annotation:'signature-ui:'+e.after}));
